CREATE TABLE migration_000013_option_snapshot AS
SELECT o.id,o.option_text
FROM chat_options o
JOIN chat_steps st ON st.id=o.step_id
JOIN chats c ON c.id=st.chat_id
WHERE c.product_context->>'content_version'='issue-103-complete';
ALTER TABLE migration_000013_option_snapshot ADD PRIMARY KEY(id);

CREATE TABLE migration_000013_reply_seed (
    topic_slug VARCHAR PRIMARY KEY,
    safe_reply TEXT NOT NULL,
    verification_reply TEXT NOT NULL,
    cautious_reply TEXT NOT NULL,
    unsafe_reply TEXT NOT NULL,
    summary_reply TEXT NOT NULL
);

